begin;
create function pg_temp.assert(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Assertion failed: %',label;end if;end$$;
create function pg_temp.denied(statement text)returns boolean language plpgsql as $$begin execute statement;return false;exception when others then return true;end$$;
select set_config('qa.billing_ws',gen_random_uuid()::text,true),set_config('qa.billing_other',gen_random_uuid()::text,true);
insert into public.workspaces(id,name,slug)values(current_setting('qa.billing_ws')::uuid,'Billing rollback fixture','billing-'||gen_random_uuid()),(current_setting('qa.billing_other')::uuid,'Other billing fixture','bill-other-'||gen_random_uuid());
do $$declare ws uuid:=current_setting('qa.billing_ws')::uuid;t uuid:=gen_random_uuid();oldtoken uuid:=gen_random_uuid();x text;begin
 perform pg_temp.assert(pg_temp.denied(format('select public.claim_stripe_webhook_event(%L,%L,false,%L,null)','evt_nullLease','invoice.paid',t)),'null lease rejected');
 x:=public.claim_stripe_webhook_event('evt_rollbackBilling1','customer.subscription.updated',false,t,900);perform pg_temp.assert(x='claimed','first claim');perform pg_temp.assert(public.claim_stripe_webhook_event('evt_rollbackBilling1','customer.subscription.updated',false,gen_random_uuid(),900)='busy','concurrent delivery busy');
 perform pg_temp.assert(not public.apply_stripe_subscription_event('evt_rollbackBilling1',oldtoken,ws,'cus_Rollback1','sub_Rollback1','revenue_recovery','active',now(),now()+interval '30 days',false,100),'wrong lease cannot update');
 perform pg_temp.assert(public.apply_stripe_subscription_event('evt_rollbackBilling1',t,ws,'cus_Rollback1','sub_Rollback1','revenue_recovery','active',now(),now()+interval '30 days',false,100),'activation atomic apply');
 perform pg_temp.assert((select status='active' and last_event_created=100 from public.workspace_subscriptions where workspace_id=ws),'active entitlement persisted');perform pg_temp.assert((select processed_at is not null and lease_token is null from public.stripe_webhook_events where event_id='evt_rollbackBilling1'),'event completed atomically');
 perform pg_temp.assert(public.claim_stripe_webhook_event('evt_rollbackBilling1','customer.subscription.updated',false,t,900)='processed','duplicate delivery no-op');
 t:=gen_random_uuid();perform public.claim_stripe_webhook_event('evt_rollbackOld','customer.subscription.deleted',false,t,900);perform public.apply_stripe_subscription_event('evt_rollbackOld',t,ws,'cus_Rollback1','sub_Rollback1','revenue_recovery','canceled',null,null,false,99);perform pg_temp.assert((select status='active' from public.workspace_subscriptions where workspace_id=ws),'out of order state preserved');
 t:=gen_random_uuid();perform public.claim_stripe_webhook_event('evt_rollbackLate','customer.subscription.updated',false,t,900);update public.stripe_webhook_events set lease_expires_at=clock_timestamp()-interval '1 second'where event_id='evt_rollbackLate';perform pg_temp.assert(not public.apply_stripe_subscription_event('evt_rollbackLate',t,ws,'cus_Rollback1','sub_Rollback1','revenue_recovery','canceled',null,null,false,101),'expired lease denied');
 oldtoken:=t;t:=gen_random_uuid();perform pg_temp.assert(public.claim_stripe_webhook_event('evt_rollbackLate','customer.subscription.updated',false,t,900)='claimed','lease takeover');perform pg_temp.assert(not public.finish_stripe_webhook_event('evt_rollbackLate',oldtoken,null),'old worker cannot finish after takeover');perform pg_temp.assert(public.finish_stripe_webhook_event('evt_rollbackLate',t,'Synthetic provider timeout'),'failure persisted for retry');perform pg_temp.assert((select processed_at is null and processing_error is not null from public.stripe_webhook_events where event_id='evt_rollbackLate'),'failed event not success');
 t:=gen_random_uuid();perform public.claim_stripe_webhook_event('evt_rollbackMode','invoice.paid',true,t,900);perform pg_temp.assert(pg_temp.denied(format('select public.apply_stripe_subscription_event(%L,%L,%L,%L,%L,%L,%L,null,null,false,102)','evt_rollbackMode',t,ws,'cus_Rollback1','sub_Rollback1','revenue_recovery','active')),'live/test isolation');
 t:=gen_random_uuid();perform public.claim_stripe_webhook_event('evt_rollbackTenant','invoice.paid',false,t,900);perform pg_temp.assert(pg_temp.denied(format('select public.apply_stripe_subscription_event(%L,%L,%L,%L,%L,%L,%L,null,null,false,102)','evt_rollbackTenant',t,current_setting('qa.billing_other'),'cus_Rollback1','sub_Rollback1','revenue_recovery','active')),'provider identity tenant rejection');
 t:=gen_random_uuid();perform public.claim_stripe_webhook_event('evt_rollbackCancel','customer.subscription.deleted',false,t,900);perform public.apply_stripe_subscription_event('evt_rollbackCancel',t,ws,'cus_Rollback1','sub_Rollback1','revenue_recovery','canceled',null,null,false,103);perform pg_temp.assert((select status='canceled' from public.workspace_subscriptions where workspace_id=ws),'cancellation reconciliation');
 perform pg_temp.assert(not has_function_privilege('authenticated','public.claim_stripe_webhook_event(text,text,boolean,uuid,integer)','execute'),'authenticated cannot claim billing events');perform pg_temp.assert(not has_function_privilege('anon','public.apply_stripe_subscription_event(text,uuid,uuid,text,text,text,text,timestamptz,timestamptz,boolean,bigint)','execute'),'anonymous cannot alter entitlement');perform pg_temp.assert(has_function_privilege('service_role','public.apply_stripe_subscription_event(text,uuid,uuid,text,text,text,text,timestamptz,timestamptz,boolean,bigint)','execute'),'webhook service can reconcile');
end$$;
rollback;
select 'Stripe database transactions passed; fixtures rolled back; no provider charges' as result;
